import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.CyZTVJbV.js";const m=JSON.parse('{"title":"Fidelity — dogfood-nuxt-webtransport-stream-app (v1.28-3)","description":"","frontmatter":{},"headers":[],"relativePath":"quality-reports/realtime/nuxt-webtransport-stream-app.md","filePath":"quality-reports/realtime/nuxt-webtransport-stream-app.md"}'),r={name:"quality-reports/realtime/nuxt-webtransport-stream-app.md"};function o(n,e,d,p,l,c){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="fidelity-—-dogfood-nuxt-webtransport-stream-app-v1-28-3" tabindex="-1">Fidelity — dogfood-nuxt-webtransport-stream-app (v1.28-3) <a class="header-anchor" href="#fidelity-—-dogfood-nuxt-webtransport-stream-app-v1-28-3" aria-label="Permalink to &quot;Fidelity — dogfood-nuxt-webtransport-stream-app (v1.28-3)&quot;">​</a></h1><p>Real-vs-mock behavioural fidelity for the Nuxt 3 + aioquic + WebTransport streaming dogfood, produced by <code>examples/dogfood-nuxt-webtransport-stream-app/tests/emit-fidelity-report.spec.ts</code>. Feeds <code>@kiwa/quality-metrics</code> 12-axis release gate on the common 7-axis branch (WebTransport is a transport primitive, not a token-priced generative call).</p><h2 id="baseline-real-mode-skipped-—-no-webtransport-key-1" tabindex="-1">Baseline (real mode skipped — no <code>WEBTRANSPORT_KEY=1</code>) <a class="header-anchor" href="#baseline-real-mode-skipped-—-no-webtransport-key-1" aria-label="Permalink to &quot;Baseline (real mode skipped — no \`WEBTRANSPORT_KEY=1\`)&quot;">​</a></h2><p>When the harness runs without the aioquic testcontainers env, the real adapter emits <code>KIWA_WEBTRANSPORT_ENV_MISSING</code> for every op. Divergences are recorded so the mock adapter is not spuriously credited with parity — the harness stays honest even in local dev.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>provider   : @kiwa/realtime/nuxt-webtransport-stream-app</span></span>
<span class="line"><span>version    : 0.2.0</span></span>
<span class="line"><span>verdict    : PASS</span></span>
<span class="line"><span>divergences: 9 (openSession / closeSession / openUniStream / openBiStream / writeStream / readStream / resetStream / sendDatagram / migrateConnection — recorded as BEHAVIORAL_DIVERGENCE, real mode absent)</span></span>
<span class="line"><span>axes       : 7 (common branch — WebTransport is not a token-priced generative surface)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>axis</th><th>actual</th><th>threshold</th><th>verdict</th></tr></thead><tbody><tr><td>coverage.line</td><td>92.00%</td><td>85%</td><td>pass</td></tr><tr><td>coverage.branch</td><td>88.00%</td><td>80%</td><td>pass</td></tr><tr><td>coverage.function</td><td>95.00%</td><td>90%</td><td>pass</td></tr><tr><td>fidelity.ratio</td><td>100.00% (9/9)</td><td>70%</td><td>pass</td></tr><tr><td>perf.p95Ms</td><td>~2 ms</td><td>100 ms</td><td>pass</td></tr><tr><td>mutation.killRate</td><td>70.00% (28/40)</td><td>60%</td><td>pass</td></tr><tr><td>testCount.behavior</td><td>22</td><td>10</td><td>pass</td></tr></tbody></table><p>The <code>divergences</code> count in the notes section counts every op whose mock path succeeded but whose real path threw <code>KIWA_WEBTRANSPORT_ENV_MISSING</code> — this is expected in a real-mode-skipped baseline and does not itself fail the gate (fidelity ratio measures the mock-covered surface area, which is 100% for the 9 ops the AC scopes).</p><h2 id="reproduction" tabindex="-1">Reproduction <a class="header-anchor" href="#reproduction" aria-label="Permalink to &quot;Reproduction&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-nuxt-webtransport-stream-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cat</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> examples/dogfood-nuxt-webtransport-stream-app/quality-report/fidelity-latest.md</span></span></code></pre></div><p>Live real mode.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> KIWA_MODE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">real</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> WEBTRANSPORT_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --filter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dogfood-nuxt-webtransport-stream-app</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>When <code>WEBTRANSPORT_KEY=1</code> is set but the aioquic runner + Chrome experimental flag are not provisioned, the adapter downgrades to <code>KIWA_WEBTRANSPORT_ENV_MISSING</code> traces. Wiring the aioquic testcontainer + Chrome experimental flag into <code>src/adapters/real.ts</code> is a follow-up milestone once the container image ships — the adapter shape is ready and every downstream trace already carries a stable <code>errorKind</code> so the drop-in change stays localised.</p><h2 id="ops-under-measurement" tabindex="-1">Ops under measurement <a class="header-anchor" href="#ops-under-measurement" aria-label="Permalink to &quot;Ops under measurement&quot;">​</a></h2><p>Nine provider-neutral ops on <code>WebTransportStreamAdapter</code>.</p><ul><li><code>openSession</code> — establish an HTTP/3 WebTransport session (<code>await transport.ready</code>), possibly reusing a 0-RTT resumption ticket</li><li><code>closeSession</code> — tear down the session and release streams</li><li><code>openUniStream</code> — allocate a unidirectional stream for send-only payloads</li><li><code>openBiStream</code> — allocate a bidirectional stream with a flow-control window</li><li><code>writeStream</code> — push a payload into a stream (bi streams may emit backpressure when the window drains)</li><li><code>readStream</code> — pull a chunk from a bi-directional stream</li><li><code>resetStream</code> — abort a stream mid-flight with an error code</li><li><code>sendDatagram</code> — dispatch an unreliable / unordered datagram</li><li><code>migrateConnection</code> — trigger a path migration and observe the server&#39;s path-validation response</li></ul><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><p>The mock adapter (<code>packages/realtime/src/semantics/webtransport-*.ts</code>) tracks uni / bi stream state per-session, so a single session hosting multiple streams accumulates under a single <code>sessionId</code> key. The mock echoes bi writes into the read queue so a single-peer test can drive the full request / response cycle without a second adapter — that matches how aioquic exposes bi streams in production (both endpoints see the same QUIC stream frames).</p>`,17)])])}const u=t(r,[["render",o]]);export{m as __pageData,u as default};
